(() => {
  let darkMode=false;try{darkMode=localStorage.getItem('platform-theme')==='dark';}catch{}
  const applyTheme=()=>{document.body.classList.toggle('dark-mode',darkMode);const b=document.getElementById('theme-toggle');if(b){b.textContent=darkMode?'Light mode':'Dark mode';b.setAttribute('aria-pressed',String(darkMode));b.setAttribute('aria-label',darkMode?'Switch to light mode':'Switch to dark mode');}const brand=document.querySelector('.brand');if(brand&&!document.querySelector('.ecosystem-nav'))brand.insertAdjacentHTML('afterend','<nav class="ecosystem-nav" aria-label="Platform media spaces"><a class="active" href="/">Audio</a><a href="/video.html">Video</a></nav>');};
  const nodes = new Map();
  const add = (id, name, parent, extra={}) => {const n={id,name,parent,...extra};nodes.set(id,n);return n;};
  add('album','The Night Bloom',null,{description:'Maya Lane · Album project',kind:'folder'});
  const songNames=['Still Water','Heatwave','Silver Lines','New Shape'];
  songNames.forEach((title,i)=>{
    const s='song'+(i+1), duration=[238,197,224,261][i];
    add(s,`${String(i+1).padStart(2,'0')} — ${title}`,'album',{kind:'folder',description:'Song workspace · Mixes, masters, references and stems'});
    ['Mixes','Masters','References','Stems'].forEach(f=>add(s+'-'+f,f,s,{kind:'folder'}));
    for(let v=4;v>=1;v--)add(s+'-mix-v'+v,'Mix v'+v,s+'-Mixes',{kind:'audio',title:title+' — Mix',version:v,current:v===4,group:s+'-mix',duration,format:v===1?'MP3 · 320 kbps · Stereo':'WAV · 24-bit · 96 kHz · Stereo',status:v===4?'In review':'Previous version',date:`Sep ${8+v}, 2026`,size:v===1?'9.1 MB':'129 MB'});
    add(s+'-master','Master v1',s+'-Masters',{kind:'audio',title:title+' — Master',version:1,current:true,group:s+'-master',duration,format:'WAV · 24-bit · 44.1 kHz · Stereo',status:'For approval',date:'Sep 12, 2026',size:'61 MB'});
    add(s+'-rough','Production rough.mp3',s+'-References',{kind:'audio',title:title+' — Production rough',version:1,current:true,group:s+'-rough',duration:duration+4,format:'MP3 · 320 kbps · Stereo',status:'Reference',date:'Sep 7, 2026',size:'9.3 MB'});
    ['Drums','Bass','Guitars','Vocals'].forEach((stem,j)=>add(s+'-stem-'+j,stem+'.wav',s+'-Stems',{kind:'audio',title:title+' — '+stem,version:1,current:true,group:s+'-stem-'+j,duration,format:'WAV · 24-bit · 96 kHz · Stereo',status:'Stem',date:'Sep 12, 2026',size:'129 MB'}));
  });
  add('references','Album References','album',{kind:'folder',description:'Shared sonic direction for the whole record'});
  add('reference','Sonic direction.mp3','references',{kind:'audio',title:'Album — Sonic direction',version:1,current:true,group:'reference',duration:184,format:'MP3 · 320 kbps · Stereo',status:'Reference',date:'Sep 5, 2026',size:'7.4 MB'});
  add('streaming-references','Add streaming reference','references',{kind:'connector',description:'Spotify, Apple Music and SoundCloud connector'});
  add('ref-spotify','Glass Gardens — Luma Vale','references',{kind:'external',provider:'Spotify',artist:'Luma Vale',description:'Sample streaming reference',status:'Linked reference',date:'Sep 11, 2026'});
  add('ref-apple','Low Light — August Radio','references',{kind:'external',provider:'Apple Music',artist:'August Radio',description:'Sample streaming reference',status:'Linked reference',date:'Sep 10, 2026'});
  add('ref-soundcloud','Afterimage (Demo) — Northline','references',{kind:'external',provider:'SoundCloud',artist:'Northline',description:'Sample streaming reference',status:'Linked reference',date:'Sep 9, 2026'});
  add('artwork','Artwork','album',{kind:'folder',description:'Space for covers, artwork and visual references'});
  add('deliverables','Deliverables','album',{kind:'folder',description:'Approved release files will live here'});
  add('marker-exports','DAW Marker Exports','album',{kind:'tool',description:'Turn version-specific timeline notes into marker files'});
  const children=id=>[...nodes.values()].filter(n=>n.parent===id);
  const trail=n=>n?[...trail(nodes.get(n.parent)),n]:[];
  const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const href=n=>'#'+encodeURIComponent(n.id);
  const notes=new Map();
  [...nodes.values()].filter(n=>n.kind==='audio').forEach(n=>notes.set(n.id,n.group.endsWith('-mix')?[{author:'Maya',time:40.32,text:n.current?'Vocal feels a touch buried entering the verse.':'Can we bring the vocal forward on the next pass?',resolved:false},{author:'Andrew',time:Math.min(121.28,n.duration-20),text:n.current?'Check the guitars through this section.':'Tighten the low end before the chorus.',resolved:false}]:[]));
  const expanded=new Set(['album','song3','song3-Mixes']);
  let selected,seconds=0,timer=null,exportSource=null,exportFormat='csv',referenceProvider='spotify',referenceResults=[],drawMarkers=()=>{};
  const fmt=s=>`${String(Math.floor(s/60)).padStart(2,'0')}:${(s%60).toFixed(3).padStart(6,'0')}`;
  const short=s=>`${Math.floor(s/60)}:${String(Math.floor(s%60)).padStart(2,'0')}`;
  function navTree(parent){return '<ul>'+children(parent).map(n=>`<li><div class="nav-row ${selected.id===n.id?'active':''}">${n.kind==='folder'?`<button class="twisty" data-toggle="${n.id}" aria-label="${expanded.has(n.id)?'Collapse':'Expand'} ${esc(n.name)}" aria-expanded="${expanded.has(n.id)}">${expanded.has(n.id)?'⌄':'›'}</button>`:`<span class="twisty">${n.kind==='tool'?'⇥':n.kind==='connector'?'＋':n.kind==='external'?'↗':'∿'}</span>`}<a href="${n.kind==='external'?'#streaming-references':href(n)}" ${selected.id===n.id?'aria-current="page"':''}>${esc(n.name)}${n.current&&n.group?.endsWith('-mix')?'<span class="nav-current">Current</span>':''}</a></div>${n.kind==='folder'&&expanded.has(n.id)?navTree(n.id):''}</li>`).join('')+'</ul>';}
  function breadcrumbs(n){return trail(n).map(x=>`<a href="${href(x)}">${esc(x.name)}</a>`).join('<span aria-hidden="true">/</span>');}
  function list(n){const items=children(n.id);return `<div class="crumb">${breadcrumbs(n)}</div><div class="folder-head"><div class="folder-title"><div class="eyebrow">${n.id==='album'?'Album / Maya Lane':'Project folder'}</div><h1>${esc(n.name)}</h1><p>${esc(n.description||`${items.length} items · Latest versions first`)}</p></div>${n.id==='album'?'<a class="btn primary" href="#song3-mix-v4">Open latest Silver Lines mix</a>':n.name==='Mixes'?`<a class="btn primary" href="${href(items[0])}">Review current mix</a>`:n.id==='references'?'<a class="btn primary" href="#streaming-references">＋ Add streaming reference</a>':''}</div>${items.length?`<div class="table-wrap"><table class="folder-table"><thead><tr><th>Name</th><th>Status</th><th>Modified</th></tr></thead><tbody>${items.map(x=>{const icon=x.kind==='folder'?'▱':x.kind==='tool'?'⇥':x.kind==='connector'?'＋':x.kind==='external'?'↗':'∿',sub=x.kind==='folder'?children(x.id).length+' items':x.kind==='tool'||x.kind==='connector'?esc(x.description):x.kind==='external'?`${esc(x.provider)} · ${esc(x.description)}`:esc(x.format)+' · '+short(x.duration),link=x.kind==='external'?`<a href="#streaming-references" data-focus-ref="${x.id}">${esc(x.name)}</a>`:`<a href="${href(x)}">${esc(x.name)}</a>`,state=x.kind==='audio'?`<span class="pill ${x.current?'current':''}">${x.current&&x.group.endsWith('-mix')?'Current · In review':esc(x.status)}</span>`:x.kind==='external'?`<span class="pill provider-${x.provider.toLowerCase().replace(/\s/g,'')}">${esc(x.provider)}</span>`:`<span class="meta">${x.kind==='tool'?'Export tool':x.kind==='connector'?'API connector':'Folder'}</span>`;return `<tr><td><div class="file-name"><span class="file-icon" aria-hidden="true">${icon}</span><div>${link}<span class="file-sub">${sub}</span></div></div></td><td>${state}</td><td class="meta">${x.date||'Sep 12, 2026'}</td></tr>`;}).join('')}</tbody></table></div>`:'<div class="empty">This folder is ready for files. No sample files added yet.</div>'}`;}

  function exportRows(scope){let assets=[...nodes.values()].filter(n=>n.kind==='audio'&&n.group?.endsWith('-mix'));
    if(scope==='current')assets=assets.filter(n=>n.current);
    if(scope==='open'&&exportSource)assets=assets.filter(n=>n.id===exportSource);
    return assets.flatMap(asset=>(notes.get(asset.id)||[]).map((note,index)=>({asset_id:asset.id,song:asset.title.replace(' — Mix',''),version:'V'+asset.version,marker:index+1,start_seconds:+note.time.toFixed(3),end_seconds:'',author:note.author,note:note.text,status:note.resolved?'resolved':'open'}))).sort((a,b)=>a.song.localeCompare(b.song)||a.start_seconds-b.start_seconds);
  }
  const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
  function makeExport(format,rows){
    const stamp=s=>{const h=Math.floor(s/3600),m=Math.floor(s%3600/60),sec=Math.floor(s%60),ms=Math.round((s%1)*1000);return `${String(h).padStart(2,'0')}:${String(m).padStart(2,'0')}:${String(sec).padStart(2,'0')}.${String(ms).padStart(3,'0')}`;};
    if(format==='json')return {name:'platform-markers.json',type:'application/json',data:JSON.stringify({schema:'platform.timeline-markers.v1',exported_at:new Date().toISOString(),markers:rows},null,2)};
    if(format==='reaper'){const data=['#','Name','Start','End','Length','Color'].join(',')+'\r\n'+rows.map((r,i)=>[i+1,`${r.song} ${r.version} — ${r.note}`,r.start_seconds,'','',0].map(csvCell).join(',')).join('\r\n');return {name:'platform-reaper-markers.csv',type:'text/csv',data};}
    if(format==='protools'){const data='Marker\tTimecode\tTrack / Version\tComment\r\n'+rows.map((r,i)=>[i+1,stamp(r.start_seconds),`${r.song} ${r.version}`,r.note].join('\t')).join('\r\n');return {name:'platform-pro-tools-marker-bridge.txt',type:'text/plain',data};}
    const headers=['asset_id','song','version','marker','start_seconds','end_seconds','author','note','status'];const data=headers.map(csvCell).join(',')+'\r\n'+rows.map(r=>headers.map(h=>csvCell(r[h])).join(',')).join('\r\n');return {name:`platform-${format==='csv'?'universal':format}-markers.csv`,type:'text/csv',data};
  }
  function exportCenter(){return `<div class="crumb">${breadcrumbs(selected)}</div><div class="folder-head export-heading"><div class="folder-title"><div class="eyebrow">Timeline data</div><h1>DAW Marker Exports</h1><p>Move review notes back into the production session.</p></div><span class="pill current">Structured from version notes</span></div><section class="export-setup"><label>Notes to include<select id="export-scope">${exportSource?'<option value="open">Last opened version</option>':''}<option value="current">Current mixes only</option><option value="all">All mix versions</option></select></label><div><span class="control-label">Export target</span><div class="export-grid">${[
      ['csv','Universal CSV','Ready','Portable spreadsheet / interchange'],['json','Structured JSON','Ready','Canonical Platform timeline data'],['reaper','REAPER marker CSV','Ready','Marker import-ready CSV'],['protools','Pro Tools','Bridge','Tab-delimited Memory Locations prep'],['logic','Logic Pro','Bridge','Marker CSV for conversion'],['ableton','Ableton Live','Bridge','Locator CSV for conversion'],['cubase','Cubase / Nuendo','Bridge','Marker CSV for conversion']
    ].map(([id,name,state,desc])=>`<button class="export-card ${exportFormat===id?'selected':''}" data-format="${id}"><span class="format-icon">${id==='json'?'{}':'⇥'}</span><span><strong>${name}</strong><small>${desc}</small></span><em class="${state==='Ready'?'ready':''}">${state}</em></button>`).join('')}</div></div></section><section class="export-preview"><div class="preview-head"><div><h2>Marker preview</h2><p id="export-summary"></p></div><button class="btn primary" id="download-export">Download export</button></div><div class="table-wrap"><table class="folder-table marker-table"><thead><tr><th>Song / version</th><th>Position</th><th>Note</th><th>Author</th></tr></thead><tbody id="marker-preview"></tbody></table></div></section><div class="demo-note"><strong>Prototype boundary:</strong> CSV, JSON and REAPER exports are generated directly. Pro Tools, Logic, Ableton, and Cubase/Nuendo currently download bridge files; native session integration would require a DAW-specific adapter or companion app.</div>`;}
  function exportInfo(){return `<h2 style="font-size:16px">Export model</h2><div class="info-card"><h3>Version-aware</h3><p>Every marker keeps its asset and version identity, so notes from V3 cannot silently overwrite V4 feedback.</p></div><div class="info-card"><h3>Point + range ready</h3><p>The schema includes start and end positions. These samples are point markers; range notes can become regions.</p></div><div class="info-card"><h3>Timebase</h3><p>Exports use exact seconds as the neutral source. DAW adapters can convert them into samples, bars and beats, or timecode.</p></div>`;}
  function refreshExport(){const scope=document.getElementById('export-scope').value,rows=exportRows(scope),body=document.getElementById('marker-preview');body.innerHTML=rows.length?rows.slice(0,20).map(r=>`<tr><td><strong>${esc(r.song)}</strong><span class="file-sub">${r.version}</span></td><td class="marker-time">${fmt(r.start_seconds)}</td><td>${esc(r.note)}</td><td>${esc(r.author)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No timeline notes in this scope.</td></tr>';document.getElementById('export-summary').textContent=`${rows.length} markers · ${new Set(rows.map(r=>r.asset_id)).size} versions · ${exportFormat==='reaper'?'REAPER CSV':exportFormat==='protools'?'Pro Tools bridge':exportFormat.toUpperCase()}`;}
  function bindExports(){document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{exportFormat=b.dataset.format;document.querySelectorAll('[data-format]').forEach(x=>x.classList.toggle('selected',x===b));refreshExport();});document.getElementById('export-scope').onchange=refreshExport;document.getElementById('download-export').onclick=()=>{const rows=exportRows(document.getElementById('export-scope').value),file=makeExport(exportFormat,rows),url=URL.createObjectURL(new Blob([file.data],{type:file.type})),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};refreshExport();}
  function info(n){return `<h2 style="font-size:16px">Project details</h2><div class="info-card"><h3>The Night Bloom</h3><p>Maya Lane · Album</p></div><div class="info-card"><h3>In this folder</h3><div class="summary-count">${children(n.id).length}</div><p>${n.name==='Mixes'?'Versions of one mix. V4 is current; previous notes stay with each version.':'Open a folder to browse, or select an audio file to review.'}</p></div><div class="info-card"><h3>Sample collaborators</h3><p>Andrew · Mix engineer<br>Maya · Artist<br>Jon · Label</p></div><div class="demo-note">Navigable mock project. Files, waveforms and collaborators are examples; no audio is stored or played.</div>`;}
  const providerNames={spotify:'Spotify',apple:'Apple Music',soundcloud:'SoundCloud',youtube:'YouTube Music',tidal:'TIDAL',bandcamp:'Bandcamp',link:'Other link'};
  const providerKey=name=>({'Apple Music':'apple','YouTube Music':'youtube','Other link':'link'}[name]||String(name).toLowerCase());
  function streamingRefs(){return children('references').filter(n=>n.kind==='external');}
  function referenceConnector(){return `<div class="crumb">${breadcrumbs(selected)}</div><div class="folder-head connector-heading"><div class="folder-title"><div class="eyebrow">Album References / Unified API</div><h1>Add streaming reference</h1><p>Search or paste a track link, preview its metadata, then attach it to this album.</p></div><span class="pill">Simulated API</span></div><section class="connector-panel"><div class="provider-tabs" role="group" aria-label="Music provider">${Object.entries(providerNames).map(([id,name])=>`<button class="provider-button ${referenceProvider===id?'selected':''}" data-provider="${id}"><span class="provider-dot ${id}"></span>${name}<small>${id==='link'?'Any public music URL':'Mock connected'}</small></button>`).join('')}</div><form class="reference-search" id="reference-search"><label for="reference-query">Track link or search</label><div><input id="reference-query" placeholder="Paste a music URL—or type a song" required><button class="btn primary" type="submit">Resolve reference</button></div><p>Mock endpoint: <code>POST /v1/references/resolve</code></p></form><div id="reference-results" aria-live="polite"></div></section><section class="linked-references"><div class="preview-head"><div><h2>Linked album references</h2><p id="linked-summary">${streamingRefs().length} streaming references</p></div><a class="btn" href="#references">Open folder</a></div><div id="linked-list">${streamingRefs().map(n=>`<article class="linked-track"><span class="provider-dot ${providerKey(n.provider)}"></span><div><strong>${esc(n.name)}</strong><small>${esc(n.provider)} · Added to The Night Bloom</small></div><button class="icon-button" data-open-source="${n.id}" aria-label="Open ${esc(n.name)} at source" title="Open at source">↗</button></article>`).join('')}</div></section><div class="demo-note"><strong>Prototype boundary:</strong> this simulates one normalized API across multiple providers. A production version would require each service's authorization, catalog rules, rate limits, and playback/linking policies. Platform would store the reference metadata and source URL—not copy or download streaming audio.</div>`;}
  function referenceInfo(){return `<h2 style="font-size:16px">Unified reference object</h2><div class="api-object"><code>{<br>&nbsp; provider,<br>&nbsp; source_id,<br>&nbsp; source_url,<br>&nbsp; title,<br>&nbsp; artist,<br>&nbsp; album,<br>&nbsp; artwork_url,<br>&nbsp; duration_ms,<br>&nbsp; added_by<br>}</code></div><div class="info-card"><h3>1 · Resolve</h3><p>A provider adapter validates a shared URL or searches that service's catalog.</p></div><div class="info-card"><h3>2 · Normalize</h3><p>Provider-specific metadata becomes one Platform reference object.</p></div><div class="info-card"><h3>3 · Attach</h3><p>The object is linked to Album References and remains traceable to its source.</p></div>`;}
  function renderReferenceResults(){const target=document.getElementById('reference-results');if(!target)return;if(!referenceResults.length){target.innerHTML='<div class="connector-empty"><strong>No result loaded</strong><span>Choose a service, then search or paste a track link.</span></div>';return;}target.innerHTML=`<div class="result-head"><h2>Resolved metadata</h2><span class="pill">Sample response</span></div>${referenceResults.map((r,i)=>`<article class="reference-result"><div class="mock-art"><span>${esc(r.title.slice(0,1).toUpperCase())}</span></div><div><strong>${esc(r.title)}</strong><span>${esc(r.artist)} · ${esc(r.album)}</span><small>${esc(r.provider)} · ${short(r.duration_ms/1000)} · ${esc(r.source_id)}</small></div><button class="btn ${i===0?'primary':''}" data-add-result="${i}">Add reference</button></article>`).join('')}`;document.querySelectorAll('[data-add-result]').forEach(b=>b.onclick=()=>addReference(+b.dataset.addResult));}
  function addReference(index){const r=referenceResults[index],id='ref-'+referenceProvider+'-'+Date.now();add(id,`${r.title} — ${r.artist}`,'references',{kind:'external',provider:r.provider,artist:r.artist,description:'Streaming catalog reference',status:'Linked reference',date:'Just now',source_id:r.source_id,source_url:r.source_url});const list=document.getElementById('linked-list');list.insertAdjacentHTML('afterbegin',`<article class="linked-track added"><span class="provider-dot ${referenceProvider}"></span><div><strong>${esc(r.title)} — ${esc(r.artist)}</strong><small>${esc(r.provider)} · Added to The Night Bloom</small></div><button class="icon-button" data-open-source="${id}" aria-label="Open ${esc(r.title)} at source" title="Open at source">↗</button></article>`);document.getElementById('linked-summary').textContent=streamingRefs().length+' streaming references';document.querySelector('.nav-tree').innerHTML=navTree('album');bindTree();bindFileActions();document.querySelector(`[data-add-result="${index}"]`).textContent='Added';document.querySelector(`[data-add-result="${index}"]`).disabled=true;}
  function bindReferenceConnector(){document.querySelectorAll('[data-provider]').forEach(b=>b.onclick=()=>{referenceProvider=b.dataset.provider;document.querySelectorAll('[data-provider]').forEach(x=>x.classList.toggle('selected',x===b));});document.getElementById('reference-search').onsubmit=e=>{e.preventDefault();const q=document.getElementById('reference-query').value.trim();if(/open\.spotify\.com/i.test(q))referenceProvider='spotify';else if(/music\.apple\.com/i.test(q))referenceProvider='apple';else if(/soundcloud\.com/i.test(q))referenceProvider='soundcloud';else if(/music\.youtube\.com/i.test(q))referenceProvider='youtube';else if(/tidal\.com/i.test(q))referenceProvider='tidal';else if(/bandcamp\.com/i.test(q))referenceProvider='bandcamp';else if(/^https?:/i.test(q))referenceProvider='link';document.querySelectorAll('[data-provider]').forEach(x=>x.classList.toggle('selected',x.dataset.provider===referenceProvider));const label=q.startsWith('http')?'Resolved track':q,provider=providerNames[referenceProvider];referenceResults=[{title:label,artist:'Sample artist',album:'Catalog result',provider,duration_ms:213000,source_id:referenceProvider+'_7F3K9',source_url:q.startsWith('http')?q:'https://example.com/sample'},{title:label+' (Live)',artist:'Sample artist',album:'Live sessions',provider,duration_ms:228000,source_id:referenceProvider+'_2L8P4',source_url:'https://example.com/sample-live'}];renderReferenceResults();bindFileActions();};renderReferenceResults();bindFileActions();}
  function review(n){const siblings=[...nodes.values()].filter(x=>x.group===n.group).sort((a,b)=>b.version-a.version);return `<a class="back" href="#${n.parent}">← Back to ${nodes.get(n.parent).name}</a><div class="title-row"><div><h1>${esc(n.title)}</h1><div class="meta">${n.name} · Andrew · ${n.date}</div></div><div class="quality"><strong>Sample source</strong><span>${n.format}</span></div></div><div class="versions">${siblings.map(x=>`<a class="version ${x.id===n.id?'active':''}" href="${href(x)}" ${x.id===n.id?'aria-current="page"':''}>V${x.version}${x.current?' · Current':''}</a>`).join('')}<button class="version" id="upload">＋ Upload version</button></div><section class="wave-card"><div class="wave" id="wave" role="slider" tabindex="0" aria-label="Sample timeline position" aria-valuemin="0" aria-valuemax="${n.duration}" aria-valuenow="0"><div class="wave-bars" id="bars"></div><div class="played" id="played"></div><div class="timeline-markers" id="timeline-markers"></div><div class="playhead" id="playhead"></div><div class="ticks">${[0,.25,.5,.75,1].map(p=>'<span>'+short(n.duration*p)+'</span>').join('')}</div></div><div class="transport"><button id="rewind" aria-label="Back ten seconds">−10</button><button class="play" id="play" aria-label="Simulate playback">▶</button><span class="time"><b id="now">00:00.000</b> / ${short(n.duration)}</span><button id="forward" aria-label="Forward ten seconds">+10</button></div></section><div class="hint">Detailed illustrative waveform · Markers link directly to version notes</div><div class="info-card"><p>${esc(n.format)} · ${n.size} · ${n.current?'Current version':'Previous version'}</p></div><div class="demo-note">Sample files only. Uploads and shared storage are not connected in this mock-up.</div>`;}
  function commentPanel(n){const items=notes.get(n.id);return `<div class="right-head"><h2>Timeline notes</h2><span class="count">V${n.version} · ${items.length} notes</span></div><div class="meta">${esc(n.name)} only</div><div id="comments">${items.length?items.map((c,i)=>`<article class="comment" data-comment-row="${i}" data-note-time="${c.time}" tabindex="0"><div class="comment-head"><span class="avatar">${esc(c.author.slice(0,2).toUpperCase())}</span><b>${esc(c.author)}</b><button class="stamp" data-time="${c.time}">${fmt(c.time)}</button></div><p>${esc(c.text)}</p><small>Sample review · ${c.resolved?'Resolved':'Open'}</small></article>`).join(''):'<div class="empty">No notes on this version yet.</div>'}</div><form class="composer" id="note-form"><input id="note" aria-label="Add a note to this version" placeholder="Add a note at 00:00.000…" maxlength="2000" required><button class="btn" type="submit">Add note</button><p class="meta">Demo notes stay until you refresh.</p></form>`;}
  function seek(s){seconds=Math.max(0,Math.min(selected.duration,s));const p=seconds/selected.duration*100;document.getElementById('playhead').style.left=p+'%';document.getElementById('played').style.clipPath=`inset(0 ${100-p}% 0 0)`;document.getElementById('now').textContent=fmt(seconds);document.getElementById('note').placeholder='Add a note at '+fmt(seconds)+'…';document.getElementById('wave').setAttribute('aria-valuenow',seconds.toFixed(3));}
  function highlightNote(index){const row=document.querySelector(`[data-comment-row="${index}"]`);if(!row)return;row.classList.remove('linked-highlight');void row.offsetWidth;row.classList.add('linked-highlight');row.scrollIntoView({behavior:'smooth',block:'center'});setTimeout(()=>row.classList.remove('linked-highlight'),1300);}
  function bindNotes(){document.querySelectorAll('[data-time]').forEach(b=>b.onclick=e=>{e.stopPropagation();seek(+b.dataset.time);highlightNote(+b.closest('[data-comment-row]').dataset.commentRow);});document.querySelectorAll('[data-comment-row]').forEach(row=>{const go=()=>{seek(+row.dataset.noteTime);highlightNote(+row.dataset.commentRow);};row.onclick=go;row.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go();}};});document.getElementById('note-form').onsubmit=e=>{e.preventDefault();const input=document.getElementById('note'),value=input.value.trim();if(!value)return;notes.get(selected.id).push({author:'You',time:seconds,text:value,resolved:false});document.querySelector('.right').innerHTML=commentPanel(selected);bindNotes();drawMarkers();seek(seconds);};}
  function stop(){clearInterval(timer);timer=null;const b=document.getElementById('play');if(b){b.textContent='▶';b.setAttribute('aria-label','Simulate playback');}}
  function bindReview(){const n=selected,wave=document.getElementById('wave'),count=Math.max(280,Math.min(520,Math.round(wave.clientWidth*.66))),seed=[...n.id].reduce((a,c)=>a+c.charCodeAt(0),0);['bars','played'].forEach(id=>{document.getElementById(id).innerHTML=Array.from({length:count},(_,i)=>{const noise=Math.abs(Math.sin((i+seed)*12.9898)*43758.5453)%1,transient=i%53<2?17:0,h=Math.min(96,7+Math.abs(Math.sin(i*.29+seed)*28)+Math.abs(Math.sin(i*.071+seed/7)*34)+noise*19+transient);return `<i class="bar" style="height:${h.toFixed(1)}%;--tone:${(32+h*.46).toFixed(1)}%;--played-tone:${(46+h*.45).toFixed(1)}%"></i>`;}).join('');});drawMarkers=()=>{const target=document.getElementById('timeline-markers');if(!target)return;target.innerHTML=(notes.get(n.id)||[]).map((c,i)=>`<button class="timeline-marker ${c.resolved?'resolved':''}" style="left:${(c.time/n.duration*100).toFixed(3)}%" data-marker-index="${i}" aria-label="Open note ${i+1} at ${fmt(c.time)}"><span>${i+1}</span></button>`).join('');target.querySelectorAll('[data-marker-index]').forEach(b=>b.onclick=e=>{e.stopPropagation();const i=+b.dataset.markerIndex;seek(notes.get(n.id)[i].time);highlightNote(i);});};drawMarkers();wave.onclick=e=>{const r=wave.getBoundingClientRect();seek((e.clientX-r.left)/r.width*n.duration);};wave.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();seek(e.key==='Home'?0:e.key==='End'?n.duration:seconds+(e.key==='ArrowRight'?1:-1));}};document.getElementById('play').onclick=()=>{if(timer){stop();return;}if(seconds>=n.duration)seek(0);document.getElementById('play').textContent='Ⅱ';document.getElementById('play').setAttribute('aria-label','Pause simulation');timer=setInterval(()=>{seek(seconds+.25);if(seconds>=n.duration)stop();},250);};document.getElementById('rewind').onclick=()=>seek(seconds-10);document.getElementById('forward').onclick=()=>seek(seconds+10);document.getElementById('upload').onclick=()=>alert('Uploads are not connected in this mock-up. Planned formats: WAV, AIFF, FLAC, MP3, AAC and M4A.');bindNotes();seek(0);}
  function render(){stop();let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{id='album';}selected=nodes.get(id)||nodes.get('album');trail(selected).slice(0,-1).forEach(n=>expanded.add(n.id));if(selected.kind==='folder')expanded.add(selected.id);const audio=selected.kind==='audio',exporting=selected.kind==='tool',connecting=selected.kind==='connector';document.querySelector('.app').innerHTML=`<header class="top"><button class="btn mobile-nav" id="browse" aria-expanded="false">Files</button><a class="brand" href="#album">platform<b>.</b></a><nav class="crumb" aria-label="Breadcrumb">${breadcrumbs(selected)}</nav><div class="top-actions">${audio?'<button class="btn hide-mobile" id="export">Export notes</button>':''}<button class="btn theme-toggle" id="theme-toggle" type="button" aria-pressed="false">Dark mode</button><button class="btn primary" id="share">Copy view link</button></div></header><div class="layout ${audio?'':'browsing'}"><aside class="side"><a class="project" href="#album"><strong>The Night Bloom</strong><small>Maya Lane · Album</small><span class="browse-label">View project overview</span></a><div class="section-title">PROJECT FILES</div><nav class="nav-tree" aria-label="Project files">${navTree('album')}</nav><div class="demo-note">Sample project · Explore freely</div></aside><main class="main">${audio?review(selected):exporting?exportCenter():connecting?referenceConnector():list(selected)}</main><aside class="side right">${audio?commentPanel(selected):exporting?exportInfo():connecting?referenceInfo():info(selected)}</aside></div>`;
  applyTheme();document.getElementById('theme-toggle').onclick=()=>{darkMode=!darkMode;try{localStorage.setItem('platform-theme',darkMode?'dark':'light');}catch{}applyTheme();};bindFileActions();document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.toggle;expanded.has(id)?expanded.delete(id):expanded.add(id);document.querySelector('.nav-tree').innerHTML=navTree('album');bindTree();});
  bindTree();applyTheme();document.getElementById('theme-toggle').onclick=()=>{darkMode=!darkMode;try{localStorage.setItem('platform-theme',darkMode?'dark':'light');}catch{}applyTheme();};document.getElementById('browse').onclick=e=>{const open=document.querySelector('.layout').classList.toggle('nav-open');e.currentTarget.setAttribute('aria-expanded',open);};document.getElementById('share').onclick=async e=>{try{await navigator.clipboard.writeText(location.href);e.target.textContent='View link copied';}catch{prompt('Copy this view link. Access remains private:',location.href);}};
  if(audio){bindReview();document.getElementById('export').onclick=()=>{exportSource=selected.id;location.hash='marker-exports';};}else if(exporting)bindExports();else if(connecting)bindReferenceConnector();}
  function bindTree(){document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const id=b.dataset.toggle;expanded.has(id)?expanded.delete(id):expanded.add(id);document.querySelector('.nav-tree').innerHTML=navTree('album');bindTree();});}
  function bindFileActions(){
    if(selected.kind==='folder'){const table=document.querySelector('.folder-table'),rows=table?.querySelectorAll('tbody tr'),items=children(selected.id);if(table&&rows&&!table.querySelector('.action-head')){const th=document.createElement('th');th.className='action-head';th.innerHTML='<span class="sr-only">File action</span>';table.querySelector('thead tr').appendChild(th);rows.forEach((row,i)=>{const n=items[i],td=document.createElement('td');td.className='file-action';if(n?.kind==='audio')td.innerHTML=`<button class="icon-button" data-download-file="${n.id}" aria-label="Download ${esc(n.name)}" title="Download original">⇩</button>`;else if(n?.kind==='external')td.innerHTML=`<button class="icon-button" data-open-source="${n.id}" aria-label="Open ${esc(n.name)} at source" title="Open at source">↗</button>`;row.appendChild(td);});}}
    if(selected.kind==='audio'&&!document.getElementById('download-current')){const b=document.createElement('button');b.id='download-current';b.className='btn file-download';b.dataset.downloadFile=selected.id;b.innerHTML='⇩ <span>Download</span>';document.querySelector('.title-row').appendChild(b);}
    document.querySelectorAll('[data-download-file]').forEach(b=>b.onclick=()=>{const n=nodes.get(b.dataset.downloadFile);alert(`Download original: ${n.name}\n\nThis mock-up has no stored audio. In production, this downloads the preserved source file (${n.format}).`);});
    document.querySelectorAll('[data-open-source]').forEach(b=>b.onclick=()=>{const n=nodes.get(b.dataset.openSource);if(n?.source_url&&/^https?:\/\//.test(n.source_url)&&!n.source_url.includes('example.com'))window.open(n.source_url,'_blank','noopener');else alert(`Open ${n?.provider||'streaming'} source\n\nThis sample reference is not connected to a live catalog URL.`);});
  }
  window.addEventListener('hashchange',render);render();
})();
